{"code": "import os
base = '/home/bob/books/Second_Generation'
rewrite_dir = os.path.join(base, 'rewrite')
if os.path.isdir(rewrite_dir):
    files = [f for f in os.listdir(rewrite_dir) if f.endswith('.md') and '_Rewrite.md' in f]
    print('Number of rewritten chapters:', len(files))
    if files:
        # Extract chapter numbers
        nums = []
        for f in files:
            # Expected format: Chapter_01_Title_Rewrite.md
            parts = f.split('_')
            if len(parts) >= 2 and parts[0] == 'Chapter':
                try:
                    num = int(parts[1])
                    nums.append(num)
                except:
                    pass
        nums.sort()
        print('Chapters rewritten:', nums)
        # Find missing chapters
        all_nums = set(range(1, 65))
        missing = all_nums - set(nums)
        print('Missing chapters:', sorted(missing)[:10], '...' if len(missing) > 10 else '')
    else:
        print('No rewritten chapters found yet.')
else:
    print('Rewrite directory does not exist')"}
